import{_ as r,l as i,o as e,c as s,v as l,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"L4 / L7 负载均衡","description":"","frontmatter":{"title":"L4 / L7 负载均衡","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/l4-l7-load-balancing.md","filePath":"cs/l4-l7-load-balancing.md","lastUpdated":1789023840000}'),L={name:"cs/l4-l7-load-balancing.md"};function h(_,a,E,m,B,P){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=l('<h1 id="l4-l7-负载均衡" tabindex="-1">L4 / L7 负载均衡 <a class="header-anchor" href="#l4-l7-负载均衡" aria-label="Permalink to &quot;L4 / L7 负载均衡&quot;">​</a></h1><div class="epigraph"><p>L4 按五元组把连接钉到后端；L7 终止协议、看 Host/路径/Cookie 再选。能力与代价一层一层上去。</p><footer>—— 据 RFC 9110；负载均衡实践；Maglev 课将细化一致性哈希整理</footer></div><p><a href="/cs/ecmp-hashing">ECMP</a> 在路由器。<a href="/cs/edge-compute">上一课</a> 要把请求分到实例。缺口是 <strong>LB 分层</strong>：L4 vs L7、粘滞、健康检查。本课不把 Maglev 算法写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多后端提供同一服务。L4（NAT 或 DR）：不看 HTTP，快，SSL 可直达后端。L7：能按 URL 分流、重试幂等 GET、塞头，但要证书与缓冲，HOL/流控在 LB 上。WS 升级、gRPC、H3 都要求 L7 懂协议。健康检查失败应摘除，否则 GeoDNS 再准也打到死进程。</p><p>不要把 DNS 轮询当健康检查。</p><p><span class="marginnote">DSR/NAT 模式是实现。本课钉层。VIP 是前端地址。</span></p><h3 id="层决定看见什么" tabindex="-1">层决定看见什么 <a class="header-anchor" href="#层决定看见什么" aria-label="Permalink to &quot;层决定看见什么&quot;">​</a></h3><p>L4 粘五元组；L7 看 Host 与路径。健康检查必要。H3/gRPC/WS 逼 L7 懂协议。DNS 轮询不是健康检查。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 L4/L7 能力表。画：VIP → 选择 → 后端。与 WFQ：LB 选服务器，WFQ 分带宽。</p>',11)),(e(),n(c,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20VIP%5B%22%E8%99%9A%E6%8B%9F%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20L4%5B%22%E4%BA%94%E5%85%83%E7%BB%84%E7%B2%98%E6%BB%9E%22%5D%0A%20%20VIP%20--%3E%20L7%5B%22%E8%A7%A3%E6%9E%90%E5%BA%94%E7%94%A8%E5%A4%B4%22%5D%0A%20%20L4%20--%3E%20BE%5B%22%E5%90%8E%E7%AB%AF%22%5D%0A%20%20L7%20--%3E%20BE%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连接迁移：L4 钉四元组，QUIC 迁移要 CID 感知（下一课 Maglev 相关）。PFC 与 LB 无关。SYN flood 打在 L4 VIP 上，cookies 可在 LB。度量：最少连接 vs 轮询，极化类似 ECMP 大象。</p><p>安全：L7 可 WAF，扩大攻击面也扩大防护点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入服务网格 sidecar 的全部。Maglev 是下一课。后课默认：L4 保连接；L7 看内容；健康检查必要。</p><p>把有状态会话只放一台且无粘滞，用户会随机丢登录。</p><p>上一课留下的缺口在本课收口；「L4 / L7 负载均衡」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/maglev-lb">Maglev</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>L4 快、协议不可见；L7 智、要终止。</li><li>粘滞与健康检查决定正确性。</li><li>新运输（H3/gRPC）逼 L7 升级。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：HTTP 语义；LB 实践。</li></ul>',10))])}const A=r(L,[["render",h]]);export{f as __pageData,A as default};
